mapper.select:
select * from ww_clean_rules where 1=1

	and id = #{id}


	and product = #{product}


	and type = #{type}

mapper.update:
    update ww_clean_rules 
    set job_ids = #{jobIds}
       ,keep_time = #{keepTime}
	   ,clear_running_job = #{clearRunningJob}
    where id = #{id}

mapper.delete:
    delete from ww_clean_rules where 1=1

      	and id in

			#{item}

mapper.select:
		select cr.*,
		  if(cr.type='JOB',(select GROUP_CONCAT(CONCAT(job_id,'^^',job_name) separator '%%') from ww_job where instr(CONCAT(',',cr.job_ids,','),CONCAT(',',job_id,',')) > 0)
                          ,(select GROUP_CONCAT(CONCAT(job_id,'^^',job_name) separator '%%') from ww_cron where instr(CONCAT(',',cr.job_ids,','),CONCAT(',',job_id,',')) > 0)
          ) job_names
		from ww_clean_rules cr where 1=1

	      	and id in

				#{item}

select cr.*, decode(cr.type,'JOB',(select listagg(job_id||'^^'||job_name,'%%') within group (order by job_id) from ww_job where instr(','||cr.job_ids||',',','||job_id||',') > 0) ,(select listagg(job_id||'^^'||job_name,'%%') within group (order by job_id) from ww_cron where instr(','||cr.job_ids||',',','||job_id||',') > 0) ) job_names FROM ww_clean_rules cr where 1=1
and id in
#{item}
